    config: resolve(root, "app", "wrangler.generated.json"),
    host: "app.skillplane.dev",
    secretNames: ["AUTHFN_SECRET", "OAUTH_TOKEN_PEPPER", "TURNSTILE_SECRET_KEY"],
  },
  mcp: {
