name: Superfunctions Docs Cloudflare Deploy

permissions:
  contents: read

on:
  push:
    branches:
      - dev
    tags:
      - superfunctions-docs-live-*
      - superfunctions-docs-datafn-live-*
      - superfunctions-docs-filefn-live-*
      - superfunctions-docs-searchfn-live-*
      - superfunctions-docs-authfn-live-*
      - superfunctions-datafn-docs-live-*
      - superfunctions-filefn-docs-live-*
      - superfunctions-searchfn-docs-live-*
      - superfunctions-authfn-docs-live-*
    paths:
      - datafn/docs/**
      - filefn/docs/**
      - searchfn/docs/**
      - authfn/docs/**
      - docsfn/**
      - packages/docs-theme/**
      - scripts/cloudflare-docs/**
      - package.json
      - package-lock.json
      - turbo.json
      - .github/workflows/superfunctions-docs-cloudflare-deploy.yml
  workflow_dispatch:
    inputs:
      product:
        description: Docs product to deploy
        required: true
        type: choice
        default: all
        options:
          - all
          - datafn
          - filefn
          - searchfn
          - authfn
      environment:
        description: Docs environment to deploy
        required: true
        type: choice
        default: dev
        options:
          - dev
          - live

jobs:
  detect:
    runs-on: ubuntu-latest
    outputs:
      environment: ${{ steps.detect.outputs.environment }}
      products: ${{ steps.detect.outputs.products }}
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - uses: actions/setup-node@v4
        with:
          node-version: 22

      - id: detect
        env:
          EVENT_NAME: ${{ github.event_name }}
          INPUT_ENVIRONMENT: ${{ github.event.inputs.environment }}
          INPUT_PRODUCT: ${{ github.event.inputs.product }}
          REF_TYPE: ${{ github.ref_type }}
          REF_NAME: ${{ github.ref_name }}
          BEFORE: ${{ github.event.before }}
          AFTER: ${{ github.sha }}
        shell: bash
        run: |
          set -euo pipefail
          node scripts/cloudflare-docs/select-products.mjs | tee /tmp/docs-deploy-detect.out
          cat /tmp/docs-deploy-detect.out >> "$GITHUB_OUTPUT"

  deploy:
    runs-on: ubuntu-latest
    needs: detect
    if: needs.detect.outputs.products != '[]'
    environment: ${{ needs.detect.outputs.environment }}
    concurrency:
      group: superfunctions-docs-cloudflare-${{ needs.detect.outputs.environment }}-${{ matrix.product }}
      cancel-in-progress: false
    strategy:
      fail-fast: false
      matrix:
        product: ${{ fromJson(needs.detect.outputs.products) }}
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: npm ci

      - name: Ensure Rollup native package
        run: node scripts/ci-install-rollup-native.mjs

      - name: Deploy docs Worker
        env:
          CLOUDFLARE_API_TOKEN: ${{ REDACTEDs.CLOUDFLARE_API_TOKEN }}
          CLOUDFLARE_ACCOUNT_ID: ${{ REDACTEDs.CLOUDFLARE_ACCOUNT_ID }}
        run: node scripts/cloudflare-docs/deploy.mjs ${{ needs.detect.outputs.environment }} --products=${{ matrix.product }}
import process from "node:process";
import { spawnSync } from "node:child_process";
import {
  existingProductIds,
  jsonArray,
  normalizeEnvironment,
  parseProducts,
  productIds,
} from "./config.mjs";

const eventName = process.env.EVENT_NAME ?? "";
const inputEnvironment = process.env.INPUT_ENVIRONMENT ?? "dev";
const inputProduct = process.env.INPUT_PRODUCT ?? "all";
const refType = process.env.REF_TYPE ?? "";
const refName = process.env.REF_NAME ?? "";

let environment;
let products;

if (eventName === "workflow_dispatch") {
  environment = normalizeEnvironment(inputEnvironment);
  if (!environment) fail(`Invalid docs environment: ${inputEnvironment}`);
  if (environment === "live") assertLiveTag(refType, refName);
  products = parseProducts(inputProduct, { existingOnly: inputProduct === "all" });
} else if (refType === "tag") {
  environment = "live";
  const product = productFromLiveTag(refName);
  if (!product) fail(`Tag '${refName}' does not match a Superfunctions docs deploy target.`);
  products = product === "all" ? existingProductIds() : [product];
} else {
  environment = "dev";
  products = productsFromChangedFiles();
}

console.log(`environment=${environment}`);
console.log(`products=${jsonArray(products)}`);

function productsFromChangedFiles() {
  const before = resolveBeforeRef();
  const after = process.env.AFTER ?? "HEAD";
  const changedFiles = git(["diff", "--name-only", before, after]).split("\n").filter(Boolean);

  const selected = new Set();
  const selectExisting = (productId) => {
    if (existingProductIds().includes(productId)) selected.add(productId);
  };

  for (const file of changedFiles) {
    if (/^(package\.json|package-lock\.json|turbo\.json|scripts\/cloudflare-docs\/|\.github\/workflows\/superfunctions-docs-cloudflare-)/.test(file)) {
      return existingProductIds();
    }
    if (/^packages\/docs-theme\//.test(file)) {
      for (const productId of existingProductIds()) selectExisting(productId);
      continue;
    }
    if (/^docsfn\//.test(file)) {
      selectExisting("authfn");
      continue;
    }
    if (/^datafn\/docs\//.test(file)) selectExisting("datafn");
    if (/^filefn\/docs\//.test(file)) selectExisting("filefn");
    if (/^searchfn\/docs\//.test(file)) selectExisting("searchfn");
    if (/^authfn\/docs\//.test(file)) selectExisting("authfn");
  }

  return [...selected];
}

function resolveBeforeRef() {
  const before = process.env.BEFORE ?? "";
  if (before && before !== "0000000000000000000000000000000000000000") {
    return before;
  }
  const after = process.env.AFTER ?? "HEAD";
  return git(["rev-parse", `${after}^`]);
}

function productFromLiveTag(tag) {
  if (/^superfunctions-docs-live-/.test(tag)) return "all";

  for (const productId of productIds()) {
    const accepted = [
      `superfunctions-docs-${productId}-live-`,
      `superfunctions-${productId}-docs-live-`,
    ];
    if (accepted.some((prefix) => tag.startsWith(prefix))) return productId;
  }

  return null;
}

function assertLiveTag(type, name) {
  if (type !== "tag" || !productFromLiveTag(name)) {
    fail("Live docs deploys must run from a Superfunctions docs live tag.");
  }
}

function git(args) {
  const result = spawnSync("git", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.status !== 0) {
    fail(result.stderr.trim() || `git ${args.join(" ")} failed`);
  }
  return result.stdout.trim();
}

function fail(message) {
  console.error(message);
  process.exit(1);
}

