#!/usr/bin/env node

import { spawnSync } from "node:child_process";

const tag = process.argv[2];
if (!tag || !/^[A-Za-z0-9][A-Za-z0-9.+-]*$/u.test(tag)) {
  throw new Error("A valid release tag is required");
}

function git(args, failureMessage) {
  const result = spawnSync("git", args, { encoding: "utf8" });
  if (result.status !== 0) {
    throw new Error(result.stderr.trim() || failureMessage);
  }
  return result.stdout.trim();
}

const head = git(["rev-parse", "HEAD^{commit}"], "Could not resolve HEAD");
const tagged = git(
  ["rev-parse", `refs/tags/${tag}^{commit}`],
  `Release tag ${tag} does not exist`,
);
if (head !== tagged) {
  throw new Error(`HEAD ${head} does not match release tag ${tag} at ${tagged}`);
}

git(
  ["merge-base", "--is-ancestor", head, "origin/main"],
  `Release tag ${tag} must point to a commit on origin/main`,
);
process.stdout.write(`${JSON.stringify({ ok: true, tag, commit: head })}\n`);

