      "--host",
      database.identity.host,
      "--port",
      database.identity.port,
      "--username",
      database.identity.username,
      "--dbname",
      database.identity.database,
      "--format=custom",
      "--snapshot",
      snapshot,
      "--no-owner",
      "--no-privileges",
