    encrypted,
    encryption: {
      algorithm: "aes-256-gcm",
      keyDerivation: "scrypt",
      scrypt: { N: 1 << 17, r: 8, p: 1 },
      salt: salt.toString("base64"),
      iv: iv.toString("base64"),
      authTag: cipher.getAuthTag().toString("base64"),
    },
  };
