    encryption.algorithm,
    key,
    Buffer.from(encryption.iv, "base64"),
  );
  decipher.setAuthTag(Buffer.from(encryption.authTag, "base64"));
  const decrypted = Buffer.concat([
    decipher.update(protectedDump.encrypted),
    decipher.final(),
  ]);
