import { spawnSync } from "node:child_process";
import {
  packagePublishDecision,
  writeGithubOutputs,
} from "./lib/release-tags.mjs";

const [packageName, requestedVersion, npmTag] = process.argv.slice(2);
if (packageName !== "skillplane" || !["latest", "next"].includes(npmTag)) {
  throw new Error("Expected the public skillplane package and a supported npm tag");
}

const result = spawnSync("npm", ["view", packageName, "dist-tags", "--json"], {
  encoding: "utf8",
  env: process.env,
  stdio: ["ignore", "pipe", "pipe"],
});
if (result.error) throw result.error;
let distTags = {};
if (result.status === 0) {
  distTags = JSON.parse(result.stdout);
} else if (!/\bE404\b/u.test(`${result.stdout ?? ""}\n${result.stderr ?? ""}`)) {
  throw new Error("Could not read the package's npm distribution tags");
}
if (!distTags || typeof distTags !== "object" || Array.isArray(distTags)) {
  throw new Error("npm distribution tags must be an object");
}
const publishedVersion = distTags[npmTag];
if (publishedVersion !== undefined && typeof publishedVersion !== "string") {
  throw new Error(`npm distribution tag ${npmTag} has an invalid version`);
}
const decision = packagePublishDecision(publishedVersion, requestedVersion);
await writeGithubOutputs({ publish: String(decision.publish) });
process.stdout.write(
  `${JSON.stringify({ ok: true, packageName, npmTag, ...decision })}\n`,
);
name: Publish tagged package

on:
  push:
    tags:
      - "skillplane-v*.*.*"
  workflow_dispatch:
    inputs:
      release_tag:
        description: "Existing release tag in the form skillplane-v<version>"
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: skillplane-npm-publish
  cancel-in-progress: false

jobs:
  verify:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    outputs:
      npm_tag: ${{ steps.resolve.outputs.npm_tag }}
      pkg_version: ${{ steps.resolve.outputs.pkg_version }}
      release_sha: ${{ steps.source.outputs.release_sha }}
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}
    steps:
      - name: Checkout release tag
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          fetch-depth: 0
          persist-credentials: false
          ref: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.sha }}

      - name: Verify tagged main revision
        id: source
        shell: bash
        run: |
          set -euo pipefail
          tagged_commit="$(git rev-parse --verify "refs/tags/${RELEASE_TAG}^{commit}")"
          head_commit="$(git rev-parse HEAD)"
          if [[ "${tagged_commit}" != "${head_commit}" ]]; then
            echo "HEAD does not match ${RELEASE_TAG}" >&2
            exit 1
          fi
          if ! git merge-base --is-ancestor "${head_commit}" origin/main; then
            echo "${RELEASE_TAG} must point to a commit on origin/main" >&2
            exit 1
          fi
          echo "release_sha=${head_commit}" >> "${GITHUB_OUTPUT}"

      - name: Set up pnpm
        uses: pnpm/action-setup@b906affcce14559ad1aafd4ab0e942779e9f58b1 # v4
        with:
          version: 11.9.0

      - name: Set up Node.js
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 22.13.0
          cache: pnpm

      - name: Resolve publish target
        id: resolve
        run: node scripts/resolve-release-tag.mjs "${RELEASE_TAG}"

      - name: Install dependencies without lifecycle scripts
        run: pnpm install --frozen-lockfile --ignore-scripts

      - name: Build reviewed native dependencies
        run: pnpm rebuild esbuild

      - name: Verify packed CLI
        run: pnpm cli:release:check

      - name: Pack verified CLI
        run: |
          mkdir -p release-artifacts
          pnpm --filter skillplane pack --pack-destination release-artifacts

      - name: Preserve verified package
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
        with:
          name: verified-skillplane-package
          path: release-artifacts/*.tgz
          if-no-files-found: error
          retention-days: 30

  publish:
    needs: verify
    runs-on: ubuntu-latest
    timeout-minutes: 10
    environment: production
    permissions:
      contents: read
      id-token: write
    steps:
      - name: Verify protected release environment
        shell: bash
        env:
          PRODUCTION_RELEASES_ENABLED: ${{ vars.PRODUCTION_RELEASES_ENABLED }}
        run: |
          if [[ "${PRODUCTION_RELEASES_ENABLED}" != "true" ]]; then
            echo "The protected production environment is not enabled for releases" >&2
            exit 1
          fi

      - name: Checkout verified release source
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          persist-credentials: false
          ref: ${{ needs.verify.outputs.release_sha }}

      - name: Set up Node.js for npm
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 22.13.0
          registry-url: https://registry.npmjs.org

      - name: Reject out-of-order npm publication
        id: order
        run: >-
          node scripts/verify-npm-release-order.mjs
          skillplane
          "${{ needs.verify.outputs.pkg_version }}"
          "${{ needs.verify.outputs.npm_tag }}"
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}

      - name: Restore verified package
        uses: actions/download-artifact@d3f86a106a0bac45b974a628896c90dbdf5c8093 # v4.3.0
        with:
          name: verified-skillplane-package
          path: release-artifacts

      - name: Publish package
        if: ${{ steps.order.outputs.publish == 'true' }}
        shell: bash
        run: |
          set -euo pipefail
          mapfile -t archives < <(find release-artifacts -maxdepth 1 -type f -name '*.tgz')
          if [[ "${#archives[@]}" -ne 1 ]]; then
            echo "Expected exactly one verified package archive" >&2
            exit 1
          fi
          npm publish "${archives[0]}" \
            --access public \
            --provenance \
            --tag "${{ needs.verify.outputs.npm_tag }}"
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}
name: Deploy tagged Cloudflare release

on:
  push:
    tags:
