import { appendFile, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import semver from "semver";

const numericIdentifier = "(?:0|[1-9]\\d*)";
const prereleaseIdentifier = "(?:0|[1-9]\\d*|\\d*[A-Za-z-][0-9A-Za-z-]*)";
const buildIdentifier = "[0-9A-Za-z-]+";
const prereleasePattern = `${prereleaseIdentifier}(?:\\.${prereleaseIdentifier})*`;
const buildPattern = `${buildIdentifier}(?:\\.${buildIdentifier})*`;

export const VERSION_PATTERN = `${numericIdentifier}\\.${numericIdentifier}\\.${numericIdentifier}(?:-${prereleasePattern})?(?:\\+${buildPattern})?`;

const packageTagPattern = new RegExp(
  `^(?<slug>[a-z0-9][a-z0-9-]*)-v(?<version>${VERSION_PATTERN})$`,
  "u",
);
const cloudflareTagPattern = new RegExp(
  `^skillplane-cloudflare-v(?<version>${numericIdentifier}\\.${numericIdentifier}\\.${numericIdentifier}(?:-${prereleasePattern})?)$`,
  "u",
);

/** Require a non-empty release tag string. */
function requireTag(tag) {
  if (typeof tag !== "string" || tag.length === 0) {
    throw new Error("Expected a release tag argument or GITHUB_REF_NAME");
  }
  return tag;
}

/** Load and validate every public package declared in the release manifest. */
export async function loadReleasePackages(repoRoot) {
  const manifestPath = resolve(repoRoot, "release-packages.json");
  const entries = JSON.parse(await readFile(manifestPath, "utf8"));
  if (!Array.isArray(entries) || entries.length === 0) {
    throw new Error("release-packages.json must contain at least one target");
  }

  const slugs = new Set();
  const names = new Set();
  const targets = [];
  for (const entry of entries) {
    if (!entry?.slug || !entry?.path || !entry?.name) {
      throw new Error(`Invalid release target: ${JSON.stringify(entry)}`);
    }
    if (slugs.has(entry.slug) || names.has(entry.name)) {
      throw new Error(`Duplicate release target: ${entry.slug}`);
    }
    slugs.add(entry.slug);
    names.add(entry.name);

    const packageJson = JSON.parse(
      await readFile(resolve(repoRoot, entry.path, "package.json"), "utf8"),
    );
    if (packageJson.name !== entry.name) {
      throw new Error(
        `Release target ${entry.slug} expected ${entry.name}, found ${packageJson.name ?? "undefined"}`,
      );
    }
    if (packageJson.private === true) {
      throw new Error(`Release target ${entry.name} is private`);
    }
    targets.push({
      slug: entry.slug,
      name: entry.name,
      version: packageJson.version,
      path: entry.path,
    });
  }
  return targets;
}

/** Resolve a package tag to its exact manifest entry and npm distribution tag. */
export async function resolvePackageRelease(tag, repoRoot) {
  const normalizedTag = requireTag(tag);
  const match = normalizedTag.match(packageTagPattern);
  if (!match?.groups) {
    throw new Error(
      `Unsupported tag format: ${normalizedTag}. Expected <package-slug>-v<version>.`,
    );
  }
  const targets = await loadReleasePackages(repoRoot);
  const target = targets.find((candidate) => candidate.slug === match.groups.slug);
  if (!target) {
    throw new Error(
      `No publishable workspace found for slug "${match.groups.slug}". Supported slugs: ${targets.map(({ slug }) => slug).join(", ")}`,
    );
  }
  if (target.version !== match.groups.version) {
    throw new Error(
      `Tag version ${match.groups.version} does not match ${target.name}@${target.version}`,
    );
  }
  return {
    tag: normalizedTag,
    ...target,
    npmTag: match.groups.version.split("+", 1)[0].includes("-") ? "next" : "latest",
  };
}

/** Resolve and validate a Cloudflare production release tag. */
export function resolveCloudflareRelease(tag) {
  const normalizedTag = requireTag(tag);
  if (normalizedTag.length > 54) {
    throw new Error("Cloudflare release tags must not exceed 54 characters");
  }
  const match = normalizedTag.match(cloudflareTagPattern);
  if (!match?.groups) {
    throw new Error(
      `Unsupported Cloudflare tag: ${normalizedTag}. Expected skillplane-cloudflare-v<version>.`,
    );
  }
  return { tag: normalizedTag, version: match.groups.version };
}

/** Compare two exact SemVer strings. */
export function compareReleaseVersions(left, right) {
  if (semver.valid(left) !== left || semver.valid(right) !== right) {
    throw new Error("Release versions must be exact SemVer values");
  }
  return semver.compare(left, right);
}

/** Compare two validated Cloudflare release tags using SemVer precedence. */
export function compareCloudflareReleaseTags(leftTag, rightTag) {
  const left = resolveCloudflareRelease(leftTag).version;
  const right = resolveCloudflareRelease(rightTag).version;
  return compareReleaseVersions(left, right);
}

/** Reject a tagged deployment that would move production backwards. */
export function assertCloudflareReleaseOrder(deployedTag, requestedTag) {
  if (compareCloudflareReleaseTags(requestedTag, deployedTag) < 0) {
    throw new Error(
      `${requestedTag} is older than deployed release ${deployedTag}; use the production rollback procedure instead`,
    );
  }
  return { deployedTag, requestedTag };
}

/** Return the highest release tag recorded in the durable deployment ledger. */
export function highestCloudflareReleaseTag(tags) {
  if (!Array.isArray(tags)) {
    throw new Error("Cloudflare release ledger must be an array");
  }
  return tags.reduce((highest, tag) => {
    resolveCloudflareRelease(tag);
    return highest === null || compareCloudflareReleaseTags(tag, highest) > 0
      ? tag
      : highest;
  }, null);
}

/** Verify the requested release against active and partially applied releases. */
export function assertCloudflareProductionOrder({
  requestedTag,
  deployedTag,
  ledgerTags,
  allowLegacyBootstrap = false,
}) {
  resolveCloudflareRelease(requestedTag);
  const ledgerTag = highestCloudflareReleaseTag(ledgerTags);
  if (ledgerTag) assertCloudflareReleaseOrder(ledgerTag, requestedTag);
  if (deployedTag !== null) {
    try {
      resolveCloudflareRelease(deployedTag);
    } catch {
      if (!allowLegacyBootstrap) {
        throw new Error(
          "The active production Worker has no recognized release tag; use the protected legacy bootstrap override only after verifying its provenance",
        );
      }
    }
    if (typeof deployedTag === "string" && deployedTag.startsWith("skillplane-cloudflare-v")) {
      assertCloudflareReleaseOrder(deployedTag, requestedTag);
    }
  }
  return { deployedTag, ledgerTag, requestedTag };
}

/** Resolve the sole active version from Wrangler's latest deployment. */
export function activeCloudflareVersionId(deployments) {
  if (!Array.isArray(deployments)) {
    throw new Error("Wrangler deployments output must be an array");
  }
  if (deployments.length === 0) return null;
  const versions = deployments.at(-1)?.versions;
  if (!Array.isArray(versions) || versions.length === 0) {
    throw new Error("Wrangler's active deployment omitted its versions");
  }
  const active = versions.find((version) => Number(version?.percentage) === 100);
  if (typeof active?.version_id !== "string") {
    throw new Error("The active Worker uses split traffic; release order is ambiguous");
  }
  return active.version_id;
}

/** Decide whether a package channel can advance to the requested version. */
export function packagePublishDecision(publishedVersion, requestedVersion) {
  if (publishedVersion === undefined) {
    compareReleaseVersions(requestedVersion, requestedVersion);
    return { publish: true, publishedVersion, requestedVersion };
  }
  const comparison = compareReleaseVersions(requestedVersion, publishedVersion);
  if (comparison < 0) {
    throw new Error(
      `${requestedVersion} is older than published channel version ${publishedVersion}`,
    );
  }
  if (comparison === 0 && requestedVersion !== publishedVersion) {
    throw new Error(
      `${requestedVersion} does not advance published channel version ${publishedVersion}`,
    );
  }
  return {
    publish: comparison > 0,
    publishedVersion,
    requestedVersion,
  };
}

/** Append single-line values to a GitHub Actions output file. */
export async function writeGithubOutputs(
  outputs,
  outputPath = process.env.GITHUB_OUTPUT,
) {
  if (!outputPath) return;
  const lines = Object.entries(outputs).map(([key, value]) => {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/u.test(key)) {
      throw new Error(`Invalid GitHub output name: ${key}`);
    }
    const normalizedValue = String(value);
    if (/[\r\n]/u.test(normalizedValue)) {
      throw new Error(`GitHub output ${key} must be a single-line value`);
    }
    return `${key}=${normalizedValue}`;
  });
  await appendFile(outputPath, `${lines.join("\n")}\n`);
}
const environmentName = "skillplane-cloudflare-release-ledger";

function configuration(environment) {
  const repository = environment.GITHUB_REPOSITORY;
  const token = environment.GH_TOKEN;
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/u.test(repository ?? "") || !token) {
    throw new Error("GitHub release ledger credentials are required");
  }
  return { repository, token };
}

function headers(token) {
  return {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${token}`,
    "X-GitHub-Api-Version": "2022-11-28",
  };
}

/** List every release tag persisted before a production migration begins. */
export async function listCloudflareReleaseLedger(
  environment = process.env,
  transport = fetch,
) {
  const { repository, token } = configuration(environment);
  const releases = [];
  for (let page = 1; page <= 1_000; page += 1) {
    const url = new URL(`https://api.github.com/repos/${repository}/deployments`);
    url.searchParams.set("environment", environmentName);
    url.searchParams.set("per_page", "100");
    url.searchParams.set("page", String(page));
    const response = await transport(url, { headers: headers(token) });
    if (!response.ok) {
      throw new Error(`GitHub release ledger read failed: ${response.status}`);
    }
    const deployments = await response.json();
    if (!Array.isArray(deployments)) {
      throw new Error("GitHub release ledger response must be an array");
    }
    for (const deployment of deployments) {
      if (deployment?.environment !== environmentName || typeof deployment.ref !== "string") {
        throw new Error("GitHub release ledger contains an invalid deployment");
      }
      releases.push(deployment.ref);
    }
    if (deployments.length < 100) return releases;
  }
  throw new Error("GitHub release ledger exceeded its pagination limit");
}

/** Persist an accepted release before the workflow begins production mutation. */
export async function recordCloudflareRelease(
  releaseTag,
  environment = process.env,
  transport = fetch,
) {
  const { repository, token } = configuration(environment);
  const response = await transport(
    `https://api.github.com/repos/${repository}/deployments`,
    {
      method: "POST",
      headers: { ...headers(token), "Content-Type": "application/json" },
      body: JSON.stringify({
        ref: releaseTag,
        task: "skillplane-cloudflare-release",
        environment: environmentName,
        description: "Skillplane Cloudflare release high-water mark",
        auto_merge: false,
        required_contexts: [],
        transient_environment: false,
        production_environment: false,
      }),
    },
  );
  if (response.status !== 201) {
    throw new Error(`GitHub release ledger write failed: ${response.status}`);
  }
  const deployment = await response.json();
  if (!Number.isInteger(deployment?.id)) {
    throw new Error("GitHub release ledger write returned an invalid deployment");
  }
  return deployment.id;
}
#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { listCloudflareReleaseLedger } from "./lib/github-release-ledger.mjs";
import {
  activeCloudflareVersionId,
  assertCloudflareProductionOrder,
  resolveCloudflareRelease,
} from "./lib/release-tags.mjs";

const workerName = "skillplane-app";

function wrangler(args) {
  const result = spawnSync("pnpm", ["exec", "wrangler", ...args], {
    encoding: "utf8",
    env: process.env,
    maxBuffer: 10 * 1024 * 1024,
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(
      `${result.stdout ?? ""}\n${result.stderr ?? ""}`.trim() ||
        `wrangler ${args.join(" ")} failed`,
    );
  }
  try {
    return JSON.parse(result.stdout);
  } catch {
    throw new Error(`wrangler ${args.join(" ")} did not return valid JSON`);
  }
}

const requestedTag = process.argv[2] ?? process.env.SKILLPLANE_RELEASE_TAG;
resolveCloudflareRelease(requestedTag);
const ledgerTags = await listCloudflareReleaseLedger();
const versionId = activeCloudflareVersionId(
  wrangler(["deployments", "list", "--name", workerName, "--json"]),
);
const version = versionId
  ? wrangler(["versions", "view", versionId, "--name", workerName, "--json"])
  : null;
const deployedTag = version?.annotations?.["workers/tag"] ?? null;
const order = assertCloudflareProductionOrder({
  requestedTag,
  deployedTag,
  ledgerTags,
  allowLegacyBootstrap: process.env.ALLOW_LEGACY_BOOTSTRAP === "true",
});
process.stdout.write(
  `${JSON.stringify({ ok: true, worker: workerName, ...order })}\n`,
);
#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import {
  packagePublishDecision,
  writeGithubOutputs,
} from "./lib/release-tags.mjs";

const [packageName, requestedVersion, npmTag] = process.argv.slice(2);
if (packageName !== "skillplane" || !["latest", "next"].includes(npmTag)) {
  throw new Error("Expected the public skillplane package and a supported npm tag");
}

const result = spawnSync("npm", ["view", packageName, "dist-tags", "--json"], {
  encoding: "utf8",
  env: process.env,
  stdio: ["ignore", "pipe", "pipe"],
});
if (result.error) throw result.error;
let distTags = {};
if (result.status === 0) {
  distTags = JSON.parse(result.stdout);
} else if (!/\bE404\b/u.test(`${result.stdout ?? ""}\n${result.stderr ?? ""}`)) {
  throw new Error("Could not read the package's npm distribution tags");
}
if (!distTags || typeof distTags !== "object" || Array.isArray(distTags)) {
  throw new Error("npm distribution tags must be an object");
}
const publishedVersion = distTags[npmTag];
if (publishedVersion !== undefined && typeof publishedVersion !== "string") {
  throw new Error(`npm distribution tag ${npmTag} has an invalid version`);
}
const decision = packagePublishDecision(publishedVersion, requestedVersion);
await writeGithubOutputs({ publish: String(decision.publish) });
process.stdout.write(
  `${JSON.stringify({ ok: true, packageName, npmTag, ...decision })}\n`,
);
name: Publish tagged package

on:
  push:
    tags:
      - "skillplane-v*.*.*"
  workflow_dispatch:
    inputs:
      release_tag:
        description: "Existing release tag in the form skillplane-v<version>"
        required: true
        type: string

permissions:
  contents: read

concurrency:
  group: skillplane-npm-publish
  cancel-in-progress: false

jobs:
  verify:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    outputs:
      npm_tag: ${{ steps.resolve.outputs.npm_tag }}
      pkg_version: ${{ steps.resolve.outputs.pkg_version }}
      release_sha: ${{ steps.source.outputs.release_sha }}
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}
    steps:
      - name: Checkout release tag
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          fetch-depth: 0
          persist-credentials: false
          ref: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.sha }}

      - name: Verify tagged main revision
        id: source
        shell: bash
        run: |
          set -euo pipefail
          tagged_commit="$(git rev-parse --verify "refs/tags/${RELEASE_TAG}^{commit}")"
          head_commit="$(git rev-parse HEAD)"
          if [[ "${tagged_commit}" != "${head_commit}" ]]; then
            echo "HEAD does not match ${RELEASE_TAG}" >&2
            exit 1
          fi
          if ! git merge-base --is-ancestor "${head_commit}" origin/main; then
            echo "${RELEASE_TAG} must point to a commit on origin/main" >&2
            exit 1
          fi
          echo "release_sha=${head_commit}" >> "${GITHUB_OUTPUT}"

      - name: Set up pnpm
        uses: pnpm/action-setup@b906affcce14559ad1aafd4ab0e942779e9f58b1 # v4
        with:
          version: 11.9.0

      - name: Set up Node.js
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 22.13.0
          cache: pnpm

      - name: Resolve publish target
        id: resolve
        run: node scripts/resolve-release-tag.mjs "${RELEASE_TAG}"

      - name: Install dependencies without lifecycle scripts
        run: pnpm install --frozen-lockfile --ignore-scripts

      - name: Build reviewed native dependencies
        run: pnpm rebuild esbuild

      - name: Verify packed CLI
        run: pnpm cli:release:check

      - name: Pack verified CLI
        run: |
          mkdir -p release-artifacts
          pnpm --filter skillplane pack --pack-destination release-artifacts

      - name: Preserve verified package
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
        with:
          name: verified-skillplane-package
          path: release-artifacts/*.tgz
          if-no-files-found: error
          retention-days: 30

  publish:
    needs: verify
    runs-on: ubuntu-latest
    timeout-minutes: 10
    environment: production
    permissions:
      contents: read
      id-token: write
    steps:
      - name: Verify protected release environment
        shell: bash
        env:
          PRODUCTION_RELEASES_ENABLED: ${{ vars.PRODUCTION_RELEASES_ENABLED }}
        run: |
          if [[ "${PRODUCTION_RELEASES_ENABLED}" != "true" ]]; then
            echo "The protected production environment is not enabled for releases" >&2
            exit 1
          fi

      - name: Checkout verified release source
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          persist-credentials: false
          ref: ${{ needs.verify.outputs.release_sha }}

      - name: Set up Node.js for npm
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 22.13.0
          registry-url: https://registry.npmjs.org

      - name: Reject out-of-order npm publication
        id: order
        run: >-
          node scripts/verify-npm-release-order.mjs
          skillplane
          "${{ needs.verify.outputs.pkg_version }}"
          "${{ needs.verify.outputs.npm_tag }}"
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}

      - name: Restore verified package
        uses: actions/download-artifact@d3f86a106a0bac45b974a628896c90dbdf5c8093 # v4.3.0
        with:
          name: verified-skillplane-package
          path: release-artifacts

      - name: Publish package
        if: ${{ steps.order.outputs.publish == 'true' }}
        shell: bash
        run: |
          set -euo pipefail
          mapfile -t archives < <(find release-artifacts -maxdepth 1 -type f -name '*.tgz')
          if [[ "${#archives[@]}" -ne 1 ]]; then
            echo "Expected exactly one verified package archive" >&2
            exit 1
          fi
          npm publish "${archives[0]}" \
            --access public \
            --provenance \
            --tag "${{ needs.verify.outputs.npm_tag }}"
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}
name: Deploy tagged Cloudflare release

on:
  push:
    tags:
      - "skillplane-cloudflare-v*.*.*"
  workflow_dispatch:
    inputs:
      release_tag:
        description: "Existing release tag in the form skillplane-cloudflare-v<version>"
        required: true
        type: string
      allow_legacy_bootstrap:
        description: "Allow an initial tagged release over a verified legacy deployment"
        required: false
        default: false
        type: boolean

permissions:
  actions: read
  contents: read
  deployments: write

jobs:
  queue:
    runs-on: ubuntu-latest
    timeout-minutes: 180
    steps:
      - name: Wait for earlier production releases
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
          REPOSITORY: ${{ github.repository }}
          CURRENT_RUN_ID: ${{ github.run_id }}
          CURRENT_RUN_NUMBER: ${{ github.run_number }}
          CURRENT_RUN_ATTEMPT: ${{ github.run_attempt }}
        run: |
          set -euo pipefail
          if [[ "${CURRENT_RUN_ATTEMPT}" != "1" ]]; then
            echo "Job re-runs are not supported for production releases; start a fresh workflow_dispatch run for the release tag" >&2
            exit 1
          fi
          workflow="deploy-cloudflare-tag.yml"
          active_statuses=(requested waiting pending queued in_progress)
          while true; do
            blockers=()
            for status in "${active_statuses[@]}"; do
              run_ids="$(
                gh api --paginate --method GET \
                  "repos/${REPOSITORY}/actions/workflows/${workflow}/runs" \
                  -f status="${status}" \
                  -f per_page=100 \
                  --jq ".workflow_runs[] | select(.id != ${CURRENT_RUN_ID}) | select(.run_number < ${CURRENT_RUN_NUMBER}) | .id"
              )"
              while IFS= read -r run_id; do
                [[ -n "${run_id}" ]] && blockers+=("${run_id}")
              done <<< "${run_ids}"
            done
            if [[ "${#blockers[@]}" -eq 0 ]]; then
              break
            fi
            echo "Waiting for ${#blockers[@]} earlier production release run(s): ${blockers[*]}"
            sleep 30
          done

  deploy:
    needs: queue
    runs-on: ubuntu-latest
    timeout-minutes: 180
    environment: production
    env:
      RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}
      SKILLPLANE_RELEASE_TAG: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.ref_name }}
      CLOUDFLARE_ACCOUNT_ID: ${{ vars.CLOUDFLARE_ACCOUNT_ID }}
      CLOUDFLARE_CONTROL_HYPERDRIVE_ID: ${{ vars.CLOUDFLARE_CONTROL_HYPERDRIVE_ID }}
      SKILLPLANE_CELL_IN_SOUTH_HYPERDRIVE_ID: ${{ vars.SKILLPLANE_CELL_IN_SOUTH_HYPERDRIVE_ID }}
      SKILLPLANE_CELL_US_EAST_HYPERDRIVE_ID: ${{ vars.SKILLPLANE_CELL_US_EAST_HYPERDRIVE_ID }}
      SKILLPLANE_PUBLIC_BUCKET: ${{ vars.SKILLPLANE_PUBLIC_BUCKET }}
      SKILLPLANE_CELL_IN_SOUTH_BUCKET: ${{ vars.SKILLPLANE_CELL_IN_SOUTH_BUCKET }}
      SKILLPLANE_CELL_US_EAST_BUCKET: ${{ vars.SKILLPLANE_CELL_US_EAST_BUCKET }}
      PUBLIC_TURNSTILE_SITE_KEY: ${{ vars.PUBLIC_TURNSTILE_SITE_KEY }}
    steps:
      - name: Reject GitHub re-run attempts
        if: ${{ github.run_attempt != '1' }}
        run: |
          echo "Job re-runs are not supported for production releases; start a fresh workflow_dispatch run for the release tag" >&2
          exit 1

      - name: Verify protected release environment
        shell: bash
        env:
          PRODUCTION_RELEASES_ENABLED: ${{ vars.PRODUCTION_RELEASES_ENABLED }}
        run: |
          if [[ "${PRODUCTION_RELEASES_ENABLED}" != "true" ]]; then
            echo "The protected production environment is not enabled for releases" >&2
            exit 1
          fi

      - name: Checkout release tag
        uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
        with:
          fetch-depth: 0
          persist-credentials: false
          ref: ${{ github.event_name == 'workflow_dispatch' && inputs.release_tag || github.sha }}

      - name: Verify tagged main revision
        shell: bash
        run: |
          set -euo pipefail
          tagged_commit="$(git rev-parse --verify "refs/tags/${RELEASE_TAG}^{commit}")"
          head_commit="$(git rev-parse HEAD)"
          if [[ "${tagged_commit}" != "${head_commit}" ]]; then
            echo "HEAD does not match ${RELEASE_TAG}" >&2
            exit 1
          fi
          if ! git merge-base --is-ancestor "${head_commit}" origin/main; then
            echo "${RELEASE_TAG} must point to a commit on origin/main" >&2
            exit 1
          fi

      - name: Set up pnpm
        uses: pnpm/action-setup@b906affcce14559ad1aafd4ab0e942779e9f58b1 # v4
        with:
          version: 11.9.0

      - name: Set up Node.js
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 22.13.0
          cache: pnpm

      - name: Resolve deployment target
        run: node scripts/resolve-cloudflare-tag.mjs "${RELEASE_TAG}"

      - name: Install dependencies without lifecycle scripts
        run: pnpm install --frozen-lockfile --ignore-scripts

      - name: Build reviewed native dependencies
        run: pnpm rebuild esbuild protobufjs sharp workerd

      - name: Reject out-of-order production release
        run: node scripts/verify-cloudflare-release-order.mjs "${RELEASE_TAG}"
        env:
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          GH_TOKEN: ${{ github.token }}
          GITHUB_REPOSITORY: ${{ github.repository }}
          ALLOW_LEGACY_BOOTSTRAP: ${{ github.event_name == 'workflow_dispatch' && inputs.allow_legacy_bootstrap }}

      - name: Validate Cloudflare release
        run: pnpm deploy:check

      - name: Record production release high-water mark
        run: node scripts/record-cloudflare-release-order.mjs "${RELEASE_TAG}"
        env:
          GH_TOKEN: ${{ github.token }}
          GITHUB_REPOSITORY: ${{ github.repository }}

      - name: Back up and migrate production topology
        run: pnpm db:migrate:topology
        env:
