+  if (result.status !== 0) {
+    throw new Error(
+      `${result.stdout ?? ""}\n${result.stderr ?? ""}`.trim() ||
+        `wrangler ${args.join(" ")} failed`,
+    );
+  }
+  try {
+    return JSON.parse(result.stdout);
+  } catch {
+    throw new Error(`wrangler ${args.join(" ")} did not return valid JSON`);
+  }
