        message:
          error instanceof RuntimeError && error.code !== "CLOUD_REQUEST_REJECTED"
            ? error.message
            : "Request failed validation or authorization; inspect inputs and run doctor",
      }),
    );
    process.exitCode = 1;
  });
}

